/**
 *  A Windows domain account the bottle's programs run as. The password is
 *  not stored here but in the system keychain (see [`super::domain`]).
 */
export type DomainAccount = {
	/**  Windows user name, e.g. `jdoe`. */
	user: string,
	/**  NetBIOS domain name, e.g. `CORP`. */
	domain: string,
	/**  DNS domain, e.g. `corp.example.com`. In upper case, also the Kerberos realm. */
	dns_domain: string,
	/**  Windows computer name; empty keeps the Mac's. */
	computer_name?: string,
	/**
	 *  Domain controller to sign in with, e.g. `dc01.corp.example.com`;
	 *  empty finds one through DNS.
	 */
	kdc?: string,
};

/**  What the domain account section shows besides the account itself. */
export type DomainStatus = {
	/**  A password is saved in the keychain. */
	has_password: boolean,
};

export type EngineKind = 
/**  x86_64 Wine on macOS. Needs Rosetta 2 on Apple Silicon. */
"x86_64-rosetta" | 
/**  ARM64 Wine on macOS, with FEX translating x86 code in-process. */
"arm64-fex" | 
/**  x86_64 Wine on x86_64 Linux. */
"x86_64-native" | 
/**  ARM64 Wine on ARM64 Linux with FEX. Behind the `arm64-fex-linux` flag. */
"arm64-fex-linux";

/**  One experimental feature. */
export type ExperimentalFlag = "per-app-engine" | "engine-ab-compare" | "simulate-macos28" | "bottle-migrate-arm64" | "fex-config-editor" | "wow64-large-address" | "graphics-dxvk-arm64ec" | "graphics-user-gptk" | "runtime-channel-nightly" | "runtime-build-from-source" | "arm64-fex-linux" | "launcher-shims";

/**
 *  The `[experimental]` section of `settings.toml`: flag id → on.
 * 
 *  Ids this version does not know are kept as they are (a newer Vinter may
 *  have written them) but never count as enabled. Entries that are not
 *  `true`/`false` are dropped rather than making the whole file unreadable.
 */
export type ExperimentalSettings = { [key in string]: boolean };

/**  One option from FEX's schema. */
export type FexOption = {
	group: string,
	name: string,
	/**  The schema's own type name, e.g. "uint32". */
	schema_type: string,
	kind: FexOptionKind,
	default: string,
	description: string,
	/**  Environment variable FEX reads it from. */
	env: string,
};

export type FexOptionKind = "bool" | "integer" | "text" | 
/**
 *  A named-value list or string list; FEX converts these itself, so
 *  Vinter only shows them.
 */
"read_only";

export type Finding = {
	/**  Stable id of the pattern, e.g. "missing_dll". */
	id: string,
	severity: Severity,
	title: string,
	detail: string,
	fix: Fix,
	/**  Log lines that matched (a few, shortened). */
	evidence: string[],
};

/**  What would fix a finding. */
export type Fix = 
/**  Install these components (winetricks verbs) into the bottle. */
{ kind: "components"; verbs: string[] } | 
/**  Switch the bottle to this graphics backend. */
{ kind: "graphics"; backend: Graphics } | 
/**  Roll the bottle back to a snapshot from before it broke. */
{ kind: "restore_snapshot" } | 
/**  Get a runtime that works: reinstall this one, or install a newer one. */
{ kind: "open_runtimes" } | 
/**  Install Rosetta 2, which Intel runtimes need on Apple Silicon. */
{ kind: "install_rosetta" } | 
/**
 *  Try the program on the other engine (an Intel bottle on Apple
 *  Silicon), or on a newer runtime.
 */
{ kind: "other_engine" } | 
/**  Nothing Vinter can do for you; the finding's detail says what to try. */
{ kind: "manual" };

/**  A flag with everything Settings and `vinter experimental list` show. */
export type FlagState = {
	flag: ExperimentalFlag,
	title: string,
	description: string,
	/**  Where its controls show up, e.g. "Bottle → Programs → Edit". */
	location: string,
	/**  What it needs to show up, e.g. "Needs an Apple Silicon bottle". */
	requirement: string | null,
	risk: Risk,
	/**  False while the feature behind it is not built yet. */
	available: boolean,
	/**  In effect now (saved, or turned on for this command). */
	enabled: boolean,
	/**  Saved in `settings.toml`. */
	saved: boolean,
};

export type Flavor = "stable" | "devel" | "staging" | "gptk";

export type Frequency = "daily" | "weekly";

/**  Graphics translation layer. Only stored in M2; applied in M4. */
