export type RecipeSummary = {
	id: string,
	name: string,
	description: string,
	homepage: string | null,
	/**  Page to get a `user_provided` installer from (the homepage if not set). */
	download_page: string | null,
	/**  Patterns for the official installer's file name. */
	installer_names: string[],
	license: string | null,
	builtin: boolean,
	/**  "download", "user_provided" or "none". */
	installer_kind: string,
	/**  For user-provided installers: what to download. */
	installer_hint: string | null,
	/**  Download size of the installer, if known. */
	download_size: number | null,
	/**  Winetricks verbs that need the user's consent. */
	winetricks_verbs: string[],
	/**  The same verbs as plain names, e.g. "Windows core fonts". */
	winetricks_names: string[],
	graphics: Graphics,
	step_count: number,
};

/**  How much can go wrong with a flag on. High-risk flags ask before turning on. */
export type Risk = "low" | "medium" | "high";

export type RunExit = {
	run_id: string,
	/**  Exit code, or null if the program was stopped by a signal. */
	code: number | null,
};

/**  A program started from Vinter that is still running. */
export type RunInfo = {
	run_id: string,
	bottle_id: string,
	program_index: number,
	name: string,
	pid: number,
	/**  RFC 3339 start time. */
	started_at: string,
	/**  Log file of this run, for `log_read`. */
	log_id: string,
};

export type RunLog = {
	run_id: string,
	line: string,
	stream: Stream,
};

/**
 *  A program started, from anywhere: the window, the menu bar, a launcher
 *  or a link.
 */
export type RunStarted = {
	info: RunInfo,
};

/**  An installed runtime. */
export type Runtime = {
	id: string,
	name: string,
	version: string,
	flavor: Flavor,
	/**  Root of the extracted build. */
	path: string,
	/**  The `wine` binary inside it. */
	wine_bin: string,
	installed_at: string,
	/**  Disk usage in bytes. */
	size: number,
	source_url: string,
	arch: string,
	engine: EngineKind,
	/**  FEX release it ships, if any. */
	fex_version: string | null,
	/**
	 *  Why its engine cannot run on this machine, if it cannot (e.g. too old
	 *  a macOS, or Rosetta hidden by `simulate-macos28`).
	 */
	unavailable: string | null,
	/**  x86_64 build on Apple Silicon: runs only with Rosetta 2. */
	needs_rosetta: boolean,
	/**  Graphics backends it supports. */
	graphics: Graphics[],
	/**  Built with Kerberos, so programs can sign in with a domain account. */
	kerberos: boolean,
	/**
	 *  Reports a bottle's domain to programs (Vinter Wine's domain patch).
	 *  Other runtimes only take over the user name.
	 */
	domain_identity: boolean,
};

/**  Release channel of a runtime build. */
export type RuntimeChannel = "stable" | 
/**
 *  Untested builds, offered only with the `runtime-channel-nightly`
 *  experimental flag.
 */
"nightly";

/**  One downloadable Wine build. */
export type RuntimeInfo = RuntimeInfo_Serialize | RuntimeInfo_Deserialize;

/**  One downloadable Wine build. */
export type RuntimeInfo_Deserialize = {
	id: string,
	name: string,
	version: string,
	flavor: Flavor,
	/**  Host OS, as in `std::env::consts::OS`. */
	os: string,
	/**  CPU architecture of the Wine binaries (macOS builds are x86_64 and run under Rosetta 2). */
	arch: string,
	url: string,
	/**  Lowercase hex sha256 of the archive. */
	sha256: string,
	/**  Download size in bytes. */
	size: number,
	format: ArchiveFormat,
	/**  Path of the `wine` binary inside the archive. */
	wine_bin: string,
	license: string,
	/**  Exact Wine source this build was made from (LGPL requirement). */
	source_url: string,
	/**  Upstream release page of the build. */
	release_url: string,
	/**  Graphics backends the build supports. */
	graphics: Graphics[],
	/**  Engine that runs it; must match `os` and `arch`. */
	engine: EngineKind,
	/**  Oldest macOS it runs on, e.g. "15.0" (its libraries are built for it). */
	min_os_version?: string | null,
	/**  FEX release it ships, for engines that translate x86 code with FEX. */
	fex_version?: string | null,
	/**  Release channel; missing means stable. */
	channel?: RuntimeChannel,
};

/**  One downloadable Wine build. */
export type RuntimeInfo_Serialize = {
	id: string,
	name: string,
	version: string,
	flavor: Flavor,
	/**  Host OS, as in `std::env::consts::OS`. */
	os: string,
	/**  CPU architecture of the Wine binaries (macOS builds are x86_64 and run under Rosetta 2). */
	arch: string,
	url: string,
	/**  Lowercase hex sha256 of the archive. */
	sha256: string,
	/**  Download size in bytes. */
	size: number,
	format: ArchiveFormat,
	/**  Path of the `wine` binary inside the archive. */
	wine_bin: string,
	license: string,
	/**  Exact Wine source this build was made from (LGPL requirement). */
	source_url: string,
	/**  Upstream release page of the build. */
	release_url: string,
	/**  Graphics backends the build supports. */
	graphics: Graphics[],
	/**  Engine that runs it; must match `os` and `arch`. */
	engine: EngineKind,
	/**  Oldest macOS it runs on, e.g. "15.0" (its libraries are built for it). */
	min_os_version: string | null,
	/**  FEX release it ships, for engines that translate x86 code with FEX. */
	fex_version: string | null,
	/**  Release channel; missing means stable. */
	channel: RuntimeChannel,
	/**  Filled in for this machine: x86_64 build on Apple Silicon. */
	needs_rosetta: boolean,
};

export type RuntimeLink = 
/**  The Wine source code the build was made from. */
"source" | 
/**  The upstream release page of the build. */
"release";

/**
 *  A newer build of the same flavor as an installed runtime: a newer Wine
 *  version, or a newer build of the same runtime (e.g. Vinter Wine 11.19
 *  build 3 for build 2).
 */
export type RuntimeUpdate = RuntimeUpdate_Serialize | RuntimeUpdate_Deserialize;

/**
 *  A newer build of the same flavor as an installed runtime: a newer Wine
 *  version, or a newer build of the same runtime (e.g. Vinter Wine 11.19
 *  build 3 for build 2).
 */
export type RuntimeUpdate_Deserialize = {
	/**  The installed runtime it replaces. */
	installed_id: string,
	installed_version: string,
	/**  Build number of the installed runtime, if its id has one. */
	installed_build: number | null,
	newer: RuntimeInfo_Deserialize,
	/**  Build number of the newer runtime, if its id has one. */
	newer_build: number | null,
	/**  Names of the bottles that use the installed runtime now. */
	bottles: string[],
};

/**
 *  A newer build of the same flavor as an installed runtime: a newer Wine
 *  version, or a newer build of the same runtime (e.g. Vinter Wine 11.19
 *  build 3 for build 2).
 */
export type RuntimeUpdate_Serialize = {
	/**  The installed runtime it replaces. */
	installed_id: string,
	installed_version: string,
	/**  Build number of the installed runtime, if its id has one. */
	installed_build: number | null,
	newer: RuntimeInfo_Serialize,
	/**  Build number of the newer runtime, if its id has one. */
	newer_build: number | null,
	/**  Names of the bottles that use the installed runtime now. */
	bottles: string[],
};

/**  A recipe saved from a bottle. */
export type SavedRecipe = {
	id: string,
	name: string,
	path: string,
	toml: string,
};

export type Settings = Settings_Serialize | Settings_Deserialize;

/**
 *  [`Settings`] as read: missing fields keep their defaults, so the API type
 *  (and its generated TS) has no optional fields.
 */
export type SettingsFile = SettingsFile_Serialize | SettingsFile_Deserialize;

/**
 *  [`Settings`] as read: missing fields keep their defaults, so the API type
 *  (and its generated TS) has no optional fields.
 */
export type SettingsFile_Deserialize = {
	new_bottle_options?: BottleOptions_Deserialize,
	default_runtime?: string | null,
	menu_bar_icon?: boolean,
	notifications?: boolean,
	check_for_updates?: boolean,
	experimental?: ExperimentalSettings,
	appearance?: Appearance,
};

/**
 *  [`Settings`] as read: missing fields keep their defaults, so the API type
 *  (and its generated TS) has no optional fields.
 */
export type SettingsFile_Serialize = {
	new_bottle_options: BottleOptions_Serialize,
	default_runtime: string | null,
	menu_bar_icon: boolean,
	notifications: boolean,
	check_for_updates: boolean,
	experimental: ExperimentalSettings,
	appearance: Appearance,
};

export type SettingsView = SettingsView_Serialize | SettingsView_Deserialize;

export type SettingsView_Deserialize = {
	/**  Kept by the system (a login item), not in `settings.toml`. */
	launch_at_login: boolean,
} & Settings_Deserialize;

export type SettingsView_Serialize = {
	/**  Kept by the system (a login item), not in `settings.toml`. */
	launch_at_login: boolean,
} & Settings_Serialize;

export type Settings_Deserialize = SettingsFile_Deserialize;

export type Settings_Serialize = {
	/**  Options new bottles start with. */
	new_bottle_options: BottleOptions_Serialize,
	/**  Runtime for new bottles, if not the newest installed one. */
	default_runtime: string | null,
	/**  Show the menu bar (tray) icon. */
	menu_bar_icon: boolean,
	/**  Notify when a long job finishes or a program fails to start. */
	notifications: boolean,
	/**  Check for a newer Vinter when it starts. */
	check_for_updates: boolean,
	/**  Experimental features turned on (see [`crate::experimental`]). */
	experimental: ExperimentalSettings,
	/**  Light or dark windows, or the system's choice. */
	appearance: Appearance,
};

export type Severity = 
/**  Likely why the program failed. */
"error" | 
/**  May cause problems. */
"warning";

/**  One known workaround. */
export type Shim = {
	id: string,
	launcher: string,
	title: string,
	why: string,
	/**  Arguments added at launch. */
	args: string[],
	/**  Where the arguments are documented. */
	source: string,
};

/**  A launcher fix that fits a program, and whether it is on. */
export type ShimView = {
	on: boolean,
} & Shim;

export type Snapshot = {
	id: string,
	label: string,
	/**  Made by Vinter before a change, rather than by hand. */
	automatic: boolean,
	/**  RFC 3339 with microseconds, so snapshots sort in the order they were made. */
	created_at: string,
};

/**  How a program was found. */
export type Source = 
/**  A Start Menu or Desktop shortcut. */
"shortcut" | 
/**  An `.exe` in Program Files without a shortcut. */
"executable";

/**  A bottle whose setup has started in the background. */
export type StartedBottle = {
	bottle_id: string,
	job_id: string,
};

/**  Output stream of a log line. */
export type Stream = "stdout" | "stderr";

export type SystemStatus = {
	/**  Version of `vinter-core`. */
	version: string,
	/**  `std::env::consts::OS`, e.g. `"macos"`. */
	os: string,
	/**  `std::env::consts::ARCH`, e.g. `"aarch64"`. */
	arch: string,
	/**  Data folder, for display only. */
	data_dir: string,
	/**  macOS version, e.g. "27.0.1"; `None` elsewhere or if unknown. */
	macos_version: string | null,
	/**  This machine can run the Apple Silicon engine (Wine without Rosetta). */
	arm64_engine: boolean,
	checks: Check[],
};

/**  Built-in Wine programs that can be opened in a bottle. */
export type Tool = "winecfg" | "regedit" | "taskmgr" | "control" | "notepad" | "explorer";

/**  What one run of the app did. */
export type Trial = {
	bottle_id: string,
	bottle: string,
	program: string,
	engine: EngineKind,
	runtime: string,
	/**  Seconds from start until it first showed a window, if it did. */
	seconds_to_window: number | null,
	/**  It exited with an error code or Wine reported an unhandled exception. */
	crashed: boolean,
	/**  It exited by itself before the trial ended. */
	exited: boolean,
	exit_code: number | null,
	/**  How long the trial watched it, in seconds. */
	watched_seconds: number | null,
	/**
	 *  Frames per second, when the graphics backend reports them in the log.
	 *  None of the current backends do, so this stays empty for now.
	 */
	fps: number | null,
	/**  Log of the run, for the Logs tab. */
	log_id: string,
};

export type UpdateInfo = {
	version: string,
	notes: string | null,
};

/**  What the last automatic check found. */
export type UpdateStatus = {
	/**  A newer Vinter, if there is one. */
	app: UpdateInfo | null,
};

/**
 *  An automatic update check finished. The interface fetches the result with
 *  `update_status` (Vinter) and `runtime_updates` (runtimes).
 */
export type UpdatesFound = null;

/**  What Vinter's data folder holds. */
export type Usage = {
	/**  Largest first. */
	bottles: BottleUsage[],
	runtimes: number,
	/**  Graphics components (DXVK and the like). */
	components: number,
	/**  Leftover downloads: installers and archives from setups that stopped. */
	downloads: number,
};

export type WindowsComponent = {
	/**  Winetricks verb, e.g. "vcrun2022". */
	verb: string,
	name: string,
	description: string,
	category: Category,
	/**  Installed in this bottle (for [`list`]). */
	installed: boolean,
};

/**  Windows version reported to programs, set with `winecfg /v`. */
export type WindowsVersion = "win11" | "win10" | "win81" | "win8" | "win7" | "winxp64";

/**  How much Wine writes to a program's log (`WINEDEBUG`). */
export type WineDebug = 
/**  Nothing from Wine itself; the program's own output is still logged. */
"off" | 
/**
 *  Wine's error messages. The default: the log doctor needs them (for
 *  example to name a missing DLL), and they are few.
 */
"errors" | 
/**
 *  Errors, warnings and unimplemented functions, plus which DLLs load
 *  and the exceptions raised. Logs get large; for troubleshooting.
 */
"verbose";

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

